<div class="section-heading"><h2>Profil Perusahaan</h2><?= badge($perusahaan['statusVerifikasi']) ?></div><p class="prose"><?= nl2br(e($perusahaan['deskripsi'])) ?></p>
<dl class="summary-list two-up"><?php foreach(['namaPerusahaan'=>'Nama Perusahaan','alamat'=>'Alamat','emailPerusahaan'=>'Email Resmi','kontak'=>'Kontak','bidangUsaha'=>'Bidang Usaha','website'=>'Website','catatanVerifikasi'=>'Catatan Verifikasi'] as $k=>$label):?><div><dt><?= e($label) ?></dt><dd><?php if($k==='website'&&$perusahaan[$k]&&safeUrl($perusahaan[$k])):?><a target="_blank" rel="noopener noreferrer" href="<?= e($perusahaan[$k]) ?>"><?= e($perusahaan[$k]) ?> ↗</a><?php else:?><?= e($perusahaan[$k]?:'—') ?><?php endif;?></dd></div><?php endforeach;?></dl>
<?php if($pending):?><form method="post" action="<?= e(url('perusahaan/keputusan')) ?>" data-company-decision><?= csrf() ?><input type="hidden" name="idPerusahaan" value="<?= (int)$perusahaan['idPerusahaan'] ?>"><input type="hidden" name="versi" value="<?= e($versi) ?>"><?php endif;?>
<hr class="section-divider"><h2>Dokumen Legalitas</h2><?php if(!$dokumen):?><p class="muted">Perusahaan belum mengunggah dokumen legalitas.</p><?php endif;?>
