<?php if($pending):?><div class="form-grid"><label>Hasil Pemeriksaan<select name="pemeriksaan[<?= (int)$d['id'] ?>][hasil]"><option value="">Belum diperiksa</option><?php foreach(['Sesuai','Tidak sesuai','Bermasalah'] as $s):?><option<?= selected($reviews[$d['id']]['hasil']??$d['hasilPemeriksaan'],$s) ?>><?= e($s) ?></option><?php endforeach;?></select></label><label>Catatan Dokumen<textarea name="pemeriksaan[<?= (int)$d['id'] ?>][catatan]" maxlength="2000" rows="2"><?= e($reviews[$d['id']]['catatan']??$d['catatan']) ?></textarea></label></div><?php else:?><p><?= e($d['catatan']?:'Tidak ada catatan tambahan.') ?></p><?php endif;?></div><?php endforeach;?>
<?php if($pending):?><hr class="section-divider"><label>Alasan / Catatan Keputusan<textarea name="alasan" maxlength="3000" rows="3" placeholder="Alasan wajib diisi untuk penolakan."><?= e(old('alasan')) ?></textarea></label><div class="actions company-actions"><button class="button danger-outline" name="keputusan" value="tolak"<?= !empty($offline)?' disabled':'' ?>>Tolak</button><button class="button" name="keputusan" value="setujui"<?= !empty($offline)?' disabled':'' ?>>Terima <?= icon('check') ?></button></div></form><?php endif;?>
<hr class="section-divider"><h2>Lowongan Perusahaan</h2><?php foreach($lowongan as $l):?><div class="list-row"><div><a href="<?= e(url('lowongan/detail',['id'=>$l['idLowongan']])) ?>"><strong><?= e($l['namaLowongan']) ?></strong></a><small><?= e($l['jenisPekerjaan']) ?> · <?= e($l['lokasiPenempatan']) ?> · <?= (int)$l['jumlahPendaftar'] ?> pendaftar</small></div><?= badge($l['statusLowongan']) ?></div><?php endforeach;?><?php if(!$lowongan):?><p class="muted">Belum ada lowongan yang dipublikasikan.</p><?php endif;?>
<hr class="section-divider"><h2>Riwayat Verifikasi</h2><?php foreach($riwayat as $h):?><article class="history-item"><div class="section-heading"><?= badge($h['hasil']) ?><small><?= tanggal($h['dibuatPada'],'d M Y, H:i') ?> WIB</small></div><p><?= e($h['catatan']) ?></p><small>Oleh <?= e($h['namaPengguna']) ?></small></article><?php endforeach;?><?php if(!$riwayat):?><p class="muted">Belum ada riwayat verifikasi.</p><?php endif;?>
<?php if($approved):?><hr class="section-divider"><form method="post" action="<?= e(url('perusahaan/hapus')) ?>"><?= csrf() ?><input type="hidden" name="idPerusahaan" value="<?= (int)$perusahaan['idPerusahaan'] ?>"><label>Alasan / Bukti Pelanggaran<textarea name="alasan" maxlength="3000" required rows="3"><?= e(old('alasan')) ?></textarea></label><button class="button danger"<?= !empty($offline)?' disabled':'' ?>>Hapus karena Pelanggaran</button></form><?php endif;?>
</section>
